const input = $input.first().json || {};

function compactJson(value) {
  try {
    return JSON.stringify(value, null, 2);
  } catch (error) {
    return String(value);
  }
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        stop_before_http: true,
        success: false,
        component_id: "C4-A",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        classification: null,
        c2b_handoff: null,
        manual_review_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C4-A will not classify input when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "classify_input") {
  return fail({
    code: "CLASSIFICATION_NOT_REQUESTED",
    message: "source.next_action is not classify_input.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!config.classification_goal) {
  return fail({
    code: "MISSING_CLASSIFICATION_GOAL",
    message: "config.classification_goal is required."
  });
}

if (!config.client_ai_profile || typeof config.client_ai_profile !== "object") {
  return fail({
    code: "MISSING_CLIENT_AI_PROFILE",
    message: "config.client_ai_profile is required."
  });
}

if (!config.client_ai_profile.client_profile || !config.client_ai_profile.classification_rules) {
  return fail({
    code: "INCOMPLETE_CLIENT_AI_PROFILE",
    message: "client_ai_profile must include at least client_profile and classification_rules."
  });
}

const rules = config.client_ai_profile.classification_rules || {};

if (!Array.isArray(rules.categories) || rules.categories.length === 0) {
  return fail({
    code: "MISSING_CLASSIFICATION_CATEGORIES",
    message: "client_ai_profile.classification_rules.categories must be a non-empty array."
  });
}

if (!config.llm || typeof config.llm !== "object") {
  return fail({
    code: "MISSING_LLM_CONFIG",
    message: "config.llm is required."
  });
}

if (!config.llm.provider || !config.llm.endpoint || !config.llm.model) {
  return fail({
    code: "INCOMPLETE_LLM_CONFIG",
    message: "config.llm must include provider, endpoint, and model."
  });
}

if (config.llm.provider !== "groq") {
  return fail({
    code: "UNSUPPORTED_LLM_PROVIDER",
    message: "C4-A v1 demo supports provider = groq.",
    details: [{ provider: config.llm.provider }]
  });
}

const profile = config.client_ai_profile;
const allowedCategories = rules.categories;

const systemInstruction = [
  "You are a client-configured AI classification component inside an automation workflow.",
  "You classify one input payload into exactly one client-defined category.",
  "Use only the provided client profile, classification rules, category list, and source payload.",
  "Do not extract a full structured profile. Do not draft messages. Do not route or execute tools.",
  "Do not invent facts, intent, urgency, or business context.",
  "Return valid JSON only. Do not include markdown fences."
].join(" ");

const outputSchema = {
  classification: {
    category: allowedCategories.join(" | "),
    priority: "high | medium | low",
    confidence: "high | medium | low",
    confidence_score: "number from 0 to 100",
    reasons: ["string"],
    risk_flags: ["string"],
    manual_review_required: "boolean",
    recommended_next_action: "string from routing_rules if available"
  }
};

const userContent = [
  "CLASSIFICATION TASK",
  compactJson({
    classification_mode: config.classification_mode || "rules_plus_ai",
    classification_goal: config.classification_goal,
    default_next_action: config.default_next_action || "route_classification"
  }),
  "",
  "SOURCE PAYLOAD",
  compactJson(source.payload || {}),
  "",
  "UPSTREAM CONTEXT",
  compactJson({
    source_component: source.component_id || null,
    metadata: source.metadata || null
  }),
  "",
  "CLIENT AI PROFILE",
  compactJson(profile),
  "",
  "CLASSIFICATION RULES TO ENFORCE",
  compactJson({
    allowed_categories: allowedCategories,
    priority_rules: rules.priority_rules || {},
    routing_rules: rules.routing_rules || {},
    manual_review_triggers: rules.manual_review_triggers || [],
    risk_manual_review_triggers: profile.risk_boundaries?.manual_review_triggers || []
  }),
  "",
  "DECISION RULES",
  compactJson({
    category_rule: "Select exactly one category from allowed_categories.",
    manual_review_rule: "Set manual_review_required true when intent/category is uncertain, confidence is low, context is missing, or manual review trigger applies.",
    confidence_score_rule: "Use 0-100. High confidence usually means 80+, medium 50-79, low below 50.",
    no_execution_rule: "Do not execute or route; only recommend next action."
  }),
  "",
  "OUTPUT JSON SCHEMA",
  compactJson(outputSchema),
  "",
  "Return JSON only with the key classification."
].join("\n");

const body = {
  model: config.llm.model,
  messages: [
    {
      role: "system",
      content: systemInstruction
    },
    {
      role: "user",
      content: userContent
    }
  ],
  temperature: config.llm.temperature ?? 0.1,
  max_tokens: config.llm.max_tokens ?? 700,
  response_format: {
    type: "json_object"
  }
};

return [
  {
    json: {
      stop_before_http: false,
      request: {
        provider: config.llm.provider,
        endpoint: config.llm.endpoint,
        body
      },
      context: {
        component_id: "C4-A",
        component_version: "v1",
        event_id: source.event_id || null,
        event_type: source.event_type || null,
        classification_mode: config.classification_mode || "rules_plus_ai",
        classification_goal: config.classification_goal,
        client_ai_profile: profile,
        source_result: source,
        default_next_action: config.default_next_action || "route_classification"
      }
    }
  }
];

const llmOutput = $input.first().json || {};
const prepared = $("Prepare Classification Request").first().json;
const context = prepared.context;

const content =
  llmOutput.choices?.[0]?.message?.content ??
  llmOutput.choices?.[0]?.text ??
  null;

let parsedJson = null;
let parseError = null;

if (content) {
  try {
    parsedJson = JSON.parse(content);
  } catch (error) {
    parseError = error.message;
  }
}

const classification = parsedJson?.classification || null;

if (!classification) {
  return [
    {
      json: {
        success: false,
        component_id: context.component_id,
        component_version: context.component_version,
        event_id: context.event_id,
        event_type: context.event_type,
        classification: null,
        c2b_handoff: null,
        manual_review_handoff: null,
        source_result: context.source_result,
        error: {
          code: parseError ? "CLASSIFICATION_PARSE_FAILED" : "MISSING_CLASSIFICATION",
          message: parseError
            ? "LLM response could not be parsed as JSON."
            : "LLM response did not include classification.",
          details: [{ raw_content: content, parse_error: parseError }]
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

const rules = context.client_ai_profile?.classification_rules || {};
const allowedCategories = Array.isArray(rules.categories) ? rules.categories : [];
const routingRules = rules.routing_rules || {};

const category = classification.category || "manual_review";
const allowedCategory = allowedCategories.includes(category);

if (!allowedCategory) {
  return [
    {
      json: {
        success: false,
        component_id: context.component_id,
        component_version: context.component_version,
        event_id: context.event_id,
        event_type: context.event_type,
        classification: null,
        c2b_handoff: null,
        manual_review_handoff: null,
        source_result: context.source_result,
        error: {
          code: "INVALID_CLASSIFICATION_CATEGORY",
          message: "LLM returned a category outside allowed categories.",
          details: [
            {
              category,
              allowed_categories: allowedCategories
            }
          ]
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

const confidenceScore = Number(classification.confidence_score ?? 0);
const manualReviewRequired =
  classification.manual_review_required === true ||
  category === "manual_review" ||
  classification.confidence === "low" ||
  confidenceScore < 50;

const recommendedNextAction =
  classification.recommended_next_action ||
  routingRules[category] ||
  "manual_review";

const normalizedClassification = {
  category,
  priority: classification.priority || "medium",
  confidence: classification.confidence || "medium",
  confidence_score: confidenceScore,
  reasons: Array.isArray(classification.reasons) ? classification.reasons : [],
  risk_flags: Array.isArray(classification.risk_flags) ? classification.risk_flags : [],
  manual_review_required: manualReviewRequired,
  recommended_next_action: recommendedNextAction,
  provider: prepared.request.provider,
  model: prepared.request.body.model,
  usage: llmOutput.usage || null,
  finish_reason: llmOutput.choices?.[0]?.finish_reason || null
};

let c2bHandoff = null;
let manualReviewHandoff = null;
let nextAction = context.default_next_action;

if (manualReviewRequired || recommendedNextAction === "manual_review") {
  manualReviewHandoff = {
    next_component: "C5-E",
    input: {
      success: true,
      component_id: "C4-A",
      component_version: "v1",
      event_id: context.event_id,
      event_type: context.event_type,
      classification: normalizedClassification,
      source_result: context.source_result,
      error: null,
      next_action: "manual_review"
    },
    config: {
      queue_type: "classification_review",
      review_reason: "Classification requires manual review",
      reviewer_email: context.client_ai_profile?.approval_rules?.primary_reviewer_email || "shwetabh.singh@lexnovahq.com",
      owner: "ops",
      priority: normalizedClassification.priority || "normal",
      allowed_actions: ["confirm_category", "change_category", "mark_spam", "route_to_lead", "route_to_support"],
      default_next_action: "notify_reviewer"
    }
  };

  nextAction = "manual_review";
} else {
  c2bHandoff = {
    next_component: "C2-B",
    input: {
      success: true,
      component_id: "C4-A",
      component_version: "v1",
      event_id: context.event_id,
      event_type: context.event_type,
      classification: normalizedClassification,
      payload: context.source_result.payload || {},
      metadata: {
        source_component: context.source_result.component_id || null,
        classification_category: normalizedClassification.category,
        classification_priority: normalizedClassification.priority,
        recommended_next_action: recommendedNextAction
      },
      error: null,
      next_action: "route_by_condition"
    },
    config: {
      route_key: "classification.recommended_next_action",
      route_value: recommendedNextAction,
      default_next_action: recommendedNextAction
    }
  };

  nextAction = "route_classification";
}

return [
  {
    json: {
      success: true,
      component_id: context.component_id,
      component_version: context.component_version,
      event_id: context.event_id,
      event_type: context.event_type,
      classification: normalizedClassification,
      c2b_handoff: c2bHandoff,
      manual_review_handoff: manualReviewHandoff,
      source_result: context.source_result,
      error: null,
      next_action: nextAction
    }
  }
];

const prepared = $input.first().json || {};

return [
  {
    json: {
      success: prepared.success,
      component_id: prepared.component_id,
      component_version: prepared.component_version,
      event_id: prepared.event_id,
      event_type: prepared.event_type,
      classification: prepared.classification,
      c2b_handoff: prepared.c2b_handoff,
      manual_review_handoff: prepared.manual_review_handoff,
      source_result: prepared.source_result,
      error: prepared.error,
      next_action: prepared.next_action
    }
  }
];
